SELECT p.*
FROM arc_profile p

    LEFT JOIN stu_student s ON s.id = p.student_id
    LEFT JOIN arc_profile bp ON bp.student_id = p.student_id
        AND bp.academic_year = p.academic_year AND bp.section_code = 'BASIC'
    LEFT JOIN arc_profile_item ci ON ci.profile_id = bp.id AND ci.field_code = 'basic.classId'
    JOIN org_class c ON c.id = 



WHERE 1 = 1

    AND p.section_code = #{sectionCode}


    AND p.status = #{status}


    AND p.academic_year = #{academicYear}


    AND c.class_code = #{classId}


    AND c.counselor_user_id = #{counselorId}

ORDER BY p.submitted_at DESC, p.id DESC

SELECT flds.studentId, flds.fieldCode, CASE WHEN flds.fieldCode = 'basic.classId' THEN c.class_code ELSE flds.valueText END AS valueText FROM ( SELECT bp.student_id AS studentId, ci.field_code AS fieldCode, ci.value_text AS valueText FROM arc_profile bp JOIN arc_profile_item ci ON ci.profile_id = bp.id LEFT JOIN stu_student s ON s.id = bp.student_id WHERE bp.section_code = 'BASIC' AND bp.academic_year = #{academicYear} AND bp.student_id IN
#{studentId}
AND ((ci.field_code = 'basic.name' AND NULLIF(TRIM(s.name), '') IS NULL) OR (ci.field_code = 'basic.classId' AND NULLIF(TRIM(s.class_code), '') IS NULL)) AND ci.field_code IN
#{fieldCode}
UNION ALL SELECT s.id AS studentId, f.code AS fieldCode, CASE f.code WHEN 'basic.name' THEN s.name ELSE TRIM(s.class_code) END AS valueText FROM stu_student s CROSS JOIN (SELECT 'basic.name' AS code UNION ALL SELECT 'basic.classId') f WHERE s.id IN #{studentId} AND f.code IN #{fieldCode} AND NULLIF(TRIM(CASE f.code WHEN 'basic.name' THEN s.name ELSE s.class_code END), '') IS NOT NULL ) flds LEFT JOIN org_class c ON flds.fieldCode = 'basic.classId' AND c.id =
